/**
 * API クライアント
 * バックエンドとの通信を担当
 */
import { 
  ApiResponse, 
  CalculationRequest, 
  CalculationResponse, 
  HistoryResponse, 
  HistoryClearResponse,
  HistoryFilter,
  API_PATHS 
} from '../types/index';

export class ApiClient {
  private static instance: ApiClient;
  private readonly baseURL: string;

  private constructor() {
    // 開発環境ではlocalhost、本番環境では適切なURLに設定
    this.baseURL = process.env.NODE_ENV === 'production' 
      ? '/api' 
      : 'http://localhost:3001';
  }

  public static getInstance(): ApiClient {
    if (!ApiClient.instance) {
      ApiClient.instance = new ApiClient();
    }
    return ApiClient.instance;
  }

  /**
   * 計算実行API
   */
  public async executeCalculation(request: CalculationRequest): Promise<CalculationResponse> {
    try {
      const response = await fetch(`${this.baseURL}${API_PATHS.CALCULATIONS}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(request),
      });

      const apiResponse: ApiResponse<CalculationResponse> = await response.json();

      if (!response.ok || !apiResponse.success) {
        throw new Error(apiResponse.success ? 'Unknown error' : apiResponse.error.message);
      }

      return apiResponse.data;
    } catch (error) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('計算処理でエラーが発生しました');
    }
  }

  /**
   * 履歴取得API
   */
  public async getHistory(filter?: HistoryFilter): Promise<HistoryResponse> {
    try {
      const url = new URL(`${this.baseURL}${API_PATHS.CALCULATIONS_HISTORY}`);
      if (filter) {
        url.searchParams.append('filter', filter);
      }

      const response = await fetch(url.toString());
      const apiResponse: ApiResponse<HistoryResponse> = await response.json();

      if (!response.ok || !apiResponse.success) {
        throw new Error(apiResponse.success ? 'Unknown error' : apiResponse.error.message);
      }

      // timestampをDateオブジェクトに変換
      const historyData = {
        ...apiResponse.data,
        history: apiResponse.data.history.map(item => ({
          ...item,
          timestamp: new Date(item.timestamp)
        }))
      };

      return historyData;
    } catch (error) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('履歴取得でエラーが発生しました');
    }
  }

  /**
   * 履歴削除API
   */
  public async clearHistory(): Promise<HistoryClearResponse> {
    try {
      const response = await fetch(`${this.baseURL}${API_PATHS.CALCULATIONS_HISTORY}`, {
        method: 'DELETE',
      });

      const apiResponse: ApiResponse<HistoryClearResponse> = await response.json();

      if (!response.ok || !apiResponse.success) {
        throw new Error(apiResponse.success ? 'Unknown error' : apiResponse.error.message);
      }

      return apiResponse.data;
    } catch (error) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('履歴削除でエラーが発生しました');
    }
  }

  /**
   * 統計情報取得API
   */
  public async getHistoryStats(): Promise<{ totalCount: number; typeStatistics: Record<string, number> }> {
    try {
      const response = await fetch(`${this.baseURL}${API_PATHS.CALCULATIONS_HISTORY}/stats`);
      
      const apiResponse: ApiResponse<{ totalCount: number; typeStatistics: Record<string, number> }> = await response.json();

      if (!response.ok || !apiResponse.success) {
        throw new Error(apiResponse.success ? 'Unknown error' : apiResponse.error.message);
      }

      return apiResponse.data;
    } catch (error) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('統計情報取得でエラーが発生しました');
    }
  }
}

export const apiClient = ApiClient.getInstance();