/**
 * API統合後の計算サービス
 * バックエンドAPIを使用して計算・履歴管理を行う
 */
import { 
  CalculationType, 
  CalculationHistory, 
  HistoryFilter,
  CalculationRequest 
} from '../types/index';
import { apiClient } from './apiClient';

export class ApiCalculationService {
  private static instance: ApiCalculationService;

  private constructor() {}

  public static getInstance(): ApiCalculationService {
    if (!ApiCalculationService.instance) {
      ApiCalculationService.instance = new ApiCalculationService();
    }
    return ApiCalculationService.instance;
  }

  /**
   * 計算を実行し、バックエンドに送信
   */
  public async executeCalculation(expression: string, type: CalculationType): Promise<number> {
    try {
      const request: CalculationRequest = { expression, type };
      const response = await apiClient.executeCalculation(request);
      return response.result;
    } catch (error) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('計算実行でエラーが発生しました');
    }
  }

  /**
   * 基本四則演算の実行（API経由）
   */
  public async executeBasicCalculation(expression: string): Promise<number> {
    return this.executeCalculation(expression, 'basic');
  }

  /**
   * 消費税計算の実行（API経由）
   */
  public async executeTaxCalculation(value: number, type: CalculationType): Promise<number> {
    if (type !== 'tax-inclusive' && type !== 'tax-exclusive') {
      throw new Error('無効な税計算タイプです');
    }
    return this.executeCalculation(value.toString(), type);
  }

  /**
   * 計算式の検証（ローカル検証 - API呼び出し前のバリデーション）
   */
  public validateExpression(expression: string): boolean {
    if (!expression || typeof expression !== 'string') {
      return false;
    }

    // 基本的な文字のみ許可
    const allowedChars = /^[0-9+\-*/.×÷() ]+$/;
    if (!allowedChars.test(expression)) {
      return false;
    }

    // 括弧の対応確認
    let openCount = 0;
    for (const char of expression) {
      if (char === '(') openCount++;
      if (char === ')') openCount--;
      if (openCount < 0) return false;
    }
    
    return openCount === 0;
  }
}

/**
 * API統合後の履歴管理サービス
 */
export class ApiHistoryService {
  /**
   * 計算履歴を取得（API経由）
   */
  public static async getHistory(filter: HistoryFilter = 'all'): Promise<CalculationHistory[]> {
    try {
      const response = await apiClient.getHistory(filter);
      return response.history;
    } catch (error) {
      console.error('履歴取得に失敗しました:', error);
      return [];
    }
  }

  /**
   * 履歴をフィルタリング（API経由 - サーバーサイドフィルタリング）
   */
  public static async getFilteredHistory(filter: HistoryFilter): Promise<CalculationHistory[]> {
    return this.getHistory(filter);
  }

  /**
   * すべての履歴を削除（API経由）
   */
  public static async clearAllHistory(): Promise<string> {
    try {
      const response = await apiClient.clearHistory();
      return response.message;
    } catch (error) {
      console.error('履歴削除に失敗しました:', error);
      throw new Error('履歴削除に失敗しました');
    }
  }

  /**
   * 履歴統計情報を取得（API経由）
   */
  public static async getHistoryStatistics(): Promise<{ totalCount: number; typeStatistics: Record<string, number> }> {
    try {
      return await apiClient.getHistoryStats();
    } catch (error) {
      console.error('統計情報取得に失敗しました:', error);
      return { totalCount: 0, typeStatistics: {} };
    }
  }
}

// インスタンス作成
export const apiCalculationService = ApiCalculationService.getInstance();

// テスト互換性のための関数エクスポート（旧API形式）
export const calculateExpression = async (expression: string, type: CalculationType): Promise<number> => {
  return await apiCalculationService.executeCalculation(expression, type);
};

export const getCalculationHistory = async (filter: HistoryFilter = 'all'): Promise<{ success: true; data: { history: any[] } }> => {
  const history = await ApiHistoryService.getHistory(filter);
  return {
    success: true,
    data: { history }
  };
};

export const clearHistory = async (): Promise<{ success: true; data: { message: string } }> => {
  const message = await ApiHistoryService.clearAllHistory();
  return {
    success: true,
    data: { message }
  };
};