/**
 * 履歴管理フック
 */
import { useState, useEffect, useCallback } from 'react';
import { CalculationHistory, HistoryFilter } from '../types/index';
import { ApiHistoryService } from '../services/apiCalculationService';

export function useHistory() {
  const [currentFilter, setCurrentFilter] = useState<HistoryFilter>('all');
  const [filteredHistory, setFilteredHistory] = useState<CalculationHistory[]>([]);

  // 履歴データを更新
  const updateHistory = useCallback(async () => {
    const allHistory = await ApiHistoryService.getHistory(currentFilter);
    setFilteredHistory(allHistory);
  }, [currentFilter]);

  // 初期読み込みと定期更新
  useEffect(() => {
    // 履歴を読み込み
    updateHistory();

    // 定期的に履歴を更新（他のタブでの変更を検出）
    const interval = setInterval(() => {
      updateHistory();
    }, 3000); // API負荷軽減のため3秒間隔に変更

    return () => clearInterval(interval);
  }, [updateHistory]);

  // フィルタ変更時の処理
  useEffect(() => {
    updateHistory();
  }, [currentFilter, updateHistory]);

  /**
   * フィルタを変更
   */
  const changeFilter = useCallback((filter: HistoryFilter) => {
    setCurrentFilter(filter);
  }, []);

  /**
   * 全履歴を削除
   */
  const clearAllHistory = useCallback(async () => {
    try {
      await ApiHistoryService.clearAllHistory();
      updateHistory();
    } catch (error) {
      console.error('履歴削除に失敗しました:', error);
    }
  }, [updateHistory]);

  /**
   * 手動で履歴を更新（計算実行後などに呼び出し）
   */
  const refreshHistory = useCallback(() => {
    updateHistory();
  }, [updateHistory]);

  return {
    history: filteredHistory,
    currentFilter,
    actions: {
      changeFilter,
      clearAllHistory,
      refreshHistory,
    },
  };
}